export type ResponseType = 'json' | 'text' | 'blob' | 'arraybuffer' | 'document' | 'stream';

export interface RequestConfig extends RequestInit {
    /** Request body payload, serialized by RequestDataMiddleware. */
    data?: unknown;
    /** Query parameters, serialized by QueryMiddleware. */
    query?: Record<string, unknown>;
    params?: Record<string, unknown>;
    /** A Criteria instance, flattened into query parameters by CriteriaMiddleware. */
    criteria?: Criteria;
    responseType?: ResponseType;
    /** Total request deadline in milliseconds (0 disables). */
    timeout?: number;
    retries?: number;
    retryDelay?: number;
    maxRetryDelay?: number;
    idempotencyKey?: string;
    /**
     * X-Organization-ID control for OrganizationMiddleware: `false` (or null / '')
     * omits the header for this request; a string or number overrides the id.
     */
    organization?: false | null | string | number;
    /** Pass `false` to skip the Authorization header for this request. */
    authorization?: false;
}

/** A fetch Response with the parsed `.data` attached by ResponseDataMiddleware. */
export interface ApiResponse<T = unknown> extends Response {
    data?: T;
    request: FetchRequest;
}

export interface EntriesListPayload<TEntry> {
    data: TEntry[];
    meta?: Record<string, unknown>;
    links?: Record<string, unknown>;
}

export interface EntryPayload<TEntry> {
    data?: TEntry;
    meta?: Record<string, unknown>;
    links?: Record<string, unknown>;
}

export interface ClientOptions {
    baseURL?: string;
    middlewares?: Middleware[];
    defaultMiddlewares?: Middleware[];
    request?: RequestConfig;
    /** Default X-Organization-ID used by OrganizationMiddleware. */
    organizationId?: string | number;
}

